#include <iostream>
using namespace std;

int main() {
    int a, b, c, d;
    cin >> a >> b >> c >> d;
    int x = a, y = b + c, z = b + d;
    if (x <= y && x <= z)
        cout << x;
    else if (y <= x && y <= z)
        cout << y;
    else
        cout << z;
    cout << endl;
    return 0;
}

#include <iostream>
#include <cstdio>
using namespace std;

int main() {
    double ans = 0.0;
    for (int i = 0; i < 12; ++i) {
        double a;
        cin >> a;
        if (a <= 800.0) {
            ans += 0.0;
        } else {
            ans += (a - 800.0) * 0.2;
        }
    }
    printf("%.2f\n", ans);
    return 0;
}
